sample_ts_interface:
// TypeScript: minimal sessioned streaming client interface
export type FragmentMeta = { requestId: string; callId: string; tool: string; offset: number; checksum: string };
export type FragmentChunk = { meta: FragmentMeta; payload: string; isFinal: boolean };

export interface ResumableSession {
  id: string;
  start(options?: { schemaUrl?: string }): Promise<void>;
  onFragment(cb: (chunk: FragmentChunk) => void): void;
  resume(manifestToken: string): Promise<void>;
  commit(): Promise<{ committedManifest: string }>;
  abort(reason?: string): Promise<void>;
}

