sample_go_interface:
// Go: lightweight resumable session primitives
package session

type FragmentMeta struct {
    RequestID string `json:"requestId"`
    CallID    string `json:"callId"`
    Tool      string `json:"tool"`
    Offset    int64  `json:"offset"`
    Checksum  string `json:"checksum"`
}

type FragmentChunk struct {
    Meta   FragmentMeta `json:"meta"`
    Payload string       `json:"payload"`
    IsFinal bool         `json:"isFinal"`
}

type ResumableSession interface {
    ID() string
    Start(schemaURL string) error
    OnFragment(func(FragmentChunk))
    Resume(manifestToken string) error
    Commit() (string, error)
    Abort(reason string) error
}

